# Forge 5 Rune Arrows using a for loop: one arrow for each letter!
for letter in "ARROW":
    forge_arrows(1)

# Pick gear automatically based on your Byte Shards!
budget = get_shards()
if budget >= 35:
    equip_boots("swift")
elif budget >= 25:
    wear_hat("explorer")
elif budget >= 5:
    forge_arrows(1)
else:
    print("Saving up more Byte Shards!")
